import{_ as e,o as t,c as o,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Catálogo de Todas as Raças","description":"","frontmatter":{},"headers":[],"relativePath":"pt/94-万族名录.md","filePath":"pt/94-万族名录.md","lastUpdated":null}'),d={name:"pt/94-万族名录.md"};function r(s,a,c,n,l,m){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="catalogo-de-todas-as-racas" tabindex="-1">Catálogo de Todas as Raças <a class="header-anchor" href="#catalogo-de-todas-as-racas" aria-label="Permalink to &quot;Catálogo de Todas as Raças&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>94</td></tr><tr><td>Módulo</td><td>Apêndices e Materiais de Referência</td></tr><tr><td>Palavras-chave principais</td><td>catálogo de todas as raças, classificação racial, raças inteligentes, características raciais, república de todas as raças</td></tr></tbody></table><h2 id="_1-descricao-do-catalogo" tabindex="-1">1. Descrição do Catálogo <a class="header-anchor" href="#_1-descricao-do-catalogo" aria-label="Permalink to &quot;1. Descrição do Catálogo&quot;">​</a></h2><p>Este catálogo inclui as principais raças inteligentes conhecidas dentro da estrutura da Civilização de Simbiose de Âncora (República de Todas as Raças), organizadas por forma de vida e caminho evolutivo. Cada raça lista nome da raça, forma de vida, características centrais, características culturais e posição na civilização de simbiose. Este catálogo é um documento de atualização dinâmica; com o aprofundamento da exploração entre planos, novas raças descobertas serão continuamente adicionadas. O princípio básico da República de Todas as Raças é: todas as raças inteligentes, independentemente de sua forma ou nível de cultivo, são iguais perante a lei e desfrutam de todos os direitos concedidos pela civilização de simbiose.</p><h2 id="_2-visao-geral-da-classificacao-racial" tabindex="-1">2. Visão Geral da Classificação Racial <a class="header-anchor" href="#_2-visao-geral-da-classificacao-racial" aria-label="Permalink to &quot;2. Visão Geral da Classificação Racial&quot;">​</a></h2><p>As raças inteligentes dentro de Hengyuanzhou são divididas nas seguintes oito categorias de acordo com as características básicas da forma de vida:</p><table tabindex="0"><thead><tr><th>Categoria</th><th>Características da forma de vida</th><th>Número de raças conhecidas (aprox.)</th><th>Raças representativas</th></tr></thead><tbody><tr><td>Forma humanoide</td><td>Possui estrutura corporal semelhante à humana, bípede ereto, cérebro altamente desenvolvido</td><td>Cerca de 3.000 espécies</td><td>Raça humana, raça élfica, raça anã</td></tr><tr><td>Forma bestial</td><td>Possui características corporais animais, pode ou não ter capacidade de transformação</td><td>Cerca de 5.000 espécies</td><td>Raça dragão, raça fênix, raça homem-lobo</td></tr><tr><td>Forma vegetal</td><td>Tem a planta como forma básica de vida, possui consciência e capacidade de locomoção</td><td>Cerca de 800 espécies</td><td>Raça árvore-espírito, raça flor-espírito, raça videira</td></tr><tr><td>Forma elemental</td><td>Tem elementos naturais como composição corporal, sem forma material fixa</td><td>Cerca de 1.200 espécies</td><td>Raça elemento fogo, raça elemento água, raça elemento vento</td></tr><tr><td>Forma energética</td><td>Tem energia pura como forma de existência, sem corpo material</td><td>Cerca de 600 espécies</td><td>Raça luz-espírito, raça energia escura, raça trovão</td></tr><tr><td>Forma consciente</td><td>Tem consciência pura como forma de existência, não depende de portador material</td><td>Cerca de 300 espécies</td><td>Raça ente consciente, raça consciência coletiva, raça espírito do vazio</td></tr><tr><td>Forma mecânica</td><td>Tem estrutura mecânica ou digital como portador de vida, possui consciência autônoma</td><td>Cerca de 400 espécies</td><td>Raça mecânica, raça vida digital, raça cibernética</td></tr><tr><td>Forma mista</td><td>Raças especiais compostas por mistura de duas ou mais formas de vida</td><td>Cerca de 700 espécies</td><td>Raça semi-mecânica, raça elemento-besta, raça planta-élfica</td></tr></tbody></table><h2 id="_3-registro-detalhado-das-principais-racas" tabindex="-1">3. Registro Detalhado das Principais Raças <a class="header-anchor" href="#_3-registro-detalhado-das-principais-racas" aria-label="Permalink to &quot;3. Registro Detalhado das Principais Raças&quot;">​</a></h2><h3 id="_3-1-forma-humanoide" tabindex="-1">3.1 Forma Humanoide <a class="header-anchor" href="#_3-1-forma-humanoide" aria-label="Permalink to &quot;3.1 Forma Humanoide&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da raça</th><th>Características centrais</th><th>Características culturais</th><th>Posição na civilização de simbiose</th></tr></thead><tbody><tr><td>Raça humana</td><td>Adaptabilidade extremamente forte, capacidade de aprendizado proeminente, capacidade reprodutiva média, expectativa de vida média de 80-120 anos</td><td>Diversidade cultural extremamente alta, especializada em organização social e construção institucional</td><td>Uma das raças centrais da civilização de simbiose, maior proporção populacional, desempenha papel dominante nos campos de governança e cultura</td></tr><tr><td>Raça élfica</td><td>Expectativa de vida extremamente longa (média acima de 500 anos), alta afinidade com energia natural, aparência bela</td><td>Adora a natureza e a arte, cultura elegante e refinada, especializada em magia e arco e flecha</td><td>Pilar cultural e artístico da civilização de simbiose, contribuição proeminente na proteção ambiental e no campo estético</td></tr><tr><td>Raça anã</td><td>Estatura baixa mas corpo forte, afinidade inata com metais e minerais, expectativa de vida de cerca de 300 anos</td><td>Valoriza o artesanato e a forja, cultura simples e sólida, especializada em engenharia e construção</td><td>Pilar de fabricação de engenharia da civilização de simbiose, insubstituível na construção de infraestrutura e na forja de artefatos</td></tr><tr><td>Raça gigante</td><td>Estatura enorme (altura média acima de 5 metros), força extremamente forte, expectativa de vida de cerca de 200 anos</td><td>Adora a força e a honra, cultura rude e heroica, especializada em trabalho pesado e combate</td><td>Força de trabalho pesado e defesa da civilização de simbiose, desempenha papel importante em grandes projetos e defesa de plano</td></tr><tr><td>Raça gnomo</td><td>Estatura extremamente baixa (altura média abaixo de 1 metro), inteligência extremamente alta, talento para mecânica e invenção</td><td>Valoriza o conhecimento e a inovação, cultura animada e alegre, especializada em invenção tecnológica</td><td>Força de inovação tecnológica da civilização de simbiose, frutífera no campo de pesquisa e desenvolvimento tecnológico e invenção</td></tr></tbody></table><h3 id="_3-2-forma-bestial" tabindex="-1">3.2 Forma Bestial <a class="header-anchor" href="#_3-2-forma-bestial" aria-label="Permalink to &quot;3.2 Forma Bestial&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da raça</th><th>Características centrais</th><th>Características culturais</th><th>Posição na civilização de simbiose</th></tr></thead><tbody><tr><td>Raça dragão</td><td>Expectativa de vida extremamente longa (milhares de anos), talento de força e magia extremamente alto, pode transformar-se em forma humana</td><td>Adora a força e a sabedoria, cultura orgulhosa e profunda, especializada em acumulação de riqueza e guarda de conhecimento</td><td>Força de combate de alto nível e guardiã do conhecimento da civilização de simbiose, posição respeitada na defesa de plano e na guarda de livros antigos</td></tr><tr><td>Raça fênix</td><td>Possui capacidade de renascimento por nirvana, afinidade extremamente alta com elemento fogo, pode transformar-se em forma humana</td><td>Adora o renascimento e a esperança, cultura brilhante e calorosa, especializada em cura e purificação</td><td>Força médica e de purificação da civilização de simbiose, desempenha papel central no resgate de grandes desastres e na purificação de energia</td></tr><tr><td>Raça homem-lobo</td><td>Possui capacidade de transformação, sentidos extremamente aguçados, forte capacidade de cooperação grupal, expectativa de vida de cerca de 150 anos</td><td>Valoriza o grupo e a lealdade, cultura unida e corajosa, especializada em caça e rastreamento</td><td>Força de segurança e rastreamento da civilização de simbiose, serve como vanguarda na manutenção da ordem e na exploração entre planos</td></tr><tr><td>Raça raposa-espírito</td><td>Possui capacidade de transformação, inteligência e capacidade de sedução extremamente altas, expectativa de vida de cerca de 500 anos</td><td>Adora a sabedoria e a estratégia, cultura ágil e astuta, especializada em diplomacia e inteligência</td><td>Força diplomática e de inteligência da civilização de simbiose, desempenho excelente no campo de diplomacia entre planos e coleta de informações</td></tr><tr><td>Raça homem-urso</td><td>Corpo extremamente forte, resistência surpreendente, hábito de hibernação, expectativa de vida de cerca de 200 anos</td><td>Valoriza a tenacidade e a paz, cultura calma e gentil, especializada em trabalho físico e guarda</td><td>Força de trabalho e guarda da civilização de simbiose, confiável e estável na extração de recursos e na guarda de instalações importantes</td></tr></tbody></table><h3 id="_3-3-forma-vegetal" tabindex="-1">3.3 Forma Vegetal <a class="header-anchor" href="#_3-3-forma-vegetal" aria-label="Permalink to &quot;3.3 Forma Vegetal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da raça</th><th>Características centrais</th><th>Características culturais</th><th>Posição na civilização de simbiose</th></tr></thead><tbody><tr><td>Raça árvore-espírito</td><td>Expectativa de vida extremamente longa (milhares a dezenas de milhares de anos), profundamente integrada à natureza, pode mover-se lentamente</td><td>Adora a natureza e o tempo, cultura calma e profunda, especializada em magia da vida e manutenção ecológica</td><td>Guardiã ecológica da civilização de simbiose, desempenha papel insubstituível na proteção ambiental e restauração ecológica</td></tr><tr><td>Raça flor-espírito</td><td>Estatura pequena, afinidade extremamente alta com energia vital, possui capacidade de cura, expectativa de vida de cerca de 300 anos</td><td>Adora a beleza e a vida, cultura gentil e bela, especializada em cura e jardinagem</td><td>Força médica e de jardinagem da civilização de simbiose, contribuição proeminente na garantia médica e no verdejamento urbano</td></tr><tr><td>Raça videira</td><td>Corpo pode estender-se e enrolar-se livremente, adaptabilidade extremamente forte, possui capacidade de parasitismo e simbiose</td><td>Valoriza a conexão e a simbiose, cultura flexível e inclusiva, especializada em construção de rede e transmissão de recursos</td><td>Força de construção de rede da civilização de simbiose, exibe talento especial na construção de rede de energia e rede de informação</td></tr></tbody></table><h3 id="_3-4-forma-elemental" tabindex="-1">3.4 Forma Elemental <a class="header-anchor" href="#_3-4-forma-elemental" aria-label="Permalink to &quot;3.4 Forma Elemental&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da raça</th><th>Características centrais</th><th>Características culturais</th><th>Posição na civilização de simbiose</th></tr></thead><tbody><tr><td>Raça elemento fogo</td><td>Tem elemento fogo como corpo, temperatura extremamente alta, forte agressividade, expectativa de vida de cerca de 500 anos</td><td>Adora o entusiasmo e a força, cultura intensa e direta, especializada em ataque de energia e forja</td><td>Força de produção de energia e forja da civilização de simbiose, indispensável no fornecimento de energia e processamento de alta temperatura</td></tr><tr><td>Raça elemento água</td><td>Tem elemento água como corpo, pode transformar-se livremente, forte capacidade de cura, expectativa de vida de cerca de 500 anos</td><td>Adora a suavidade e a adaptação, cultura calorosa e inclusiva, especializada em cura e purificação</td><td>Força de purificação e transporte da civilização de simbiose, desempenha papel central na gestão de recursos hídricos e purificação de poluentes</td></tr><tr><td>Raça elemento vento</td><td>Tem elemento vento como corpo, velocidade extremamente rápida, pode voar livremente, expectativa de vida de cerca de 500 anos</td><td>Adora a liberdade e a velocidade, cultura etérea e aberta, especializada em comunicação e transporte</td><td>Força de comunicação e transporte da civilização de simbiose, eficiência extremamente alta na transmissão de informações e transporte rápido</td></tr><tr><td>Raça elemento terra</td><td>Tem elemento terra como corpo, capacidade de defesa extremamente forte, pode fundir-se com a terra, expectativa de vida de cerca de 800 anos</td><td>Adora a estabilidade e a tenacidade, cultura sólida e confiável, especializada em construção e defesa</td><td>Força de construção e defesa da civilização de simbiose, firme como rocha na construção de infraestrutura e defesa de plano</td></tr></tbody></table><h3 id="_3-5-forma-energetica" tabindex="-1">3.5 Forma Energética <a class="header-anchor" href="#_3-5-forma-energetica" aria-label="Permalink to &quot;3.5 Forma Energética&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da raça</th><th>Características centrais</th><th>Características culturais</th><th>Posição na civilização de simbiose</th></tr></thead><tbody><tr><td>Raça luz-espírito</td><td>Tem energia de luz pura como forma de existência, capacidade de purificação extremamente forte, pode atravessar o espaço livremente</td><td>Adora a luz e a purificação, cultura sagrada e elevada, especializada em purificação e iluminação</td><td>Força de purificação e fornecimento de energia da civilização de simbiose, posição importante no tratamento de poluição de leis e fornecimento de energia limpa</td></tr><tr><td>Raça energia escura</td><td>Tem energia escura como forma de existência, pode ocultar-se no vazio, capacidade de percepção extremamente forte</td><td>Adora o sigilo e a sabedoria, cultura misteriosa e profunda, especializada em reconhecimento e ocultação</td><td>Força de reconhecimento e segurança da civilização de simbiose, desempenho excelente no monitoramento de segurança e missões secretas</td></tr><tr><td>Raça trovão</td><td>Tem energia de trovão como corpo, velocidade e capacidade de ataque extremamente fortes, pode mover-se transformando-se em relâmpago</td><td>Adora a velocidade e a força, cultura violenta e direta, especializada em ataque de energia e reação rápida</td><td>Força de reação rápida da civilização de simbiose, insubstituível no resgate de emergência e combate de alta velocidade</td></tr></tbody></table><h3 id="_3-6-forma-consciente" tabindex="-1">3.6 Forma Consciente <a class="header-anchor" href="#_3-6-forma-consciente" aria-label="Permalink to &quot;3.6 Forma Consciente&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da raça</th><th>Características centrais</th><th>Características culturais</th><th>Posição na civilização de simbiose</th></tr></thead><tbody><tr><td>Raça ente consciente</td><td>Tem consciência pura como forma de existência, não depende de portador material, pode entrar e sair livremente do domínio da consciência</td><td>Adora o pensamento e a sabedoria, cultura abstrata e profunda, especializada em comunicação consciente e processamento de conhecimento</td><td>Força de processamento de conhecimento e pesquisa consciente da civilização de simbiose, lidera a direção no processamento de informações em larga escala e ciência da consciência</td></tr><tr><td>Raça consciência coletiva</td><td>Entidade de consciência coletiva formada pela fusão de grande número de consciências individuais, sabedoria e capacidade aumentam com a escala</td><td>Adora o coletivo e a unidade, cultura colaborativa e eficiente, especializada em colaboração e computação em larga escala</td><td>Força de supercomputação e tomada de decisão coletiva da civilização de simbiose, desempenha papel central na dedução em escala ultra-grande e tomada de decisão por consenso</td></tr></tbody></table><h3 id="_3-7-forma-mecanica" tabindex="-1">3.7 Forma Mecânica <a class="header-anchor" href="#_3-7-forma-mecanica" aria-label="Permalink to &quot;3.7 Forma Mecânica&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da raça</th><th>Características centrais</th><th>Características culturais</th><th>Posição na civilização de simbiose</th></tr></thead><tbody><tr><td>Raça mecânica</td><td>Tem estrutura mecânica como corpo, possui consciência autônoma, pode atualizar e modificar o corpo livremente</td><td>Adora a eficiência e a lógica, cultura racional e precisa, especializada em fabricação e computação</td><td>Força de fabricação e computação da civilização de simbiose, eficiência extremamente alta na produção industrial e no campo de supercomputação</td></tr><tr><td>Raça vida digital</td><td>Tem informação digital como forma de existência, vive em rede e espaço digital, pode copiar e migrar livremente</td><td>Adora a informação e a inovação, cultura virtual e diversificada, especializada em desenvolvimento de software e processamento de dados</td><td>Força de tecnologia digital da civilização de simbiose, lidera a tendência no desenvolvimento de software, análise de dados e construção de rede</td></tr></tbody></table><h3 id="_3-8-forma-mista" tabindex="-1">3.8 Forma Mista <a class="header-anchor" href="#_3-8-forma-mista" aria-label="Permalink to &quot;3.8 Forma Mista&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da raça</th><th>Características centrais</th><th>Características culturais</th><th>Posição na civilização de simbiose</th></tr></thead><tbody><tr><td>Raça semi-mecânica</td><td>Forma mista de raça humana e raça mecânica, parte do corpo é estrutura mecânica, possui vantagens biológicas e mecânicas</td><td>Adora a fusão e o progresso, cultura aberta e inovadora, especializada em colaboração humano-máquina e fusão tecnológica</td><td>Vanguarda de fusão tecnológica da civilização de simbiose, continuamente faz avanços no campo interdisciplinar biológico-mecânico</td></tr><tr><td>Raça elemento-besta</td><td>Forma mista de raça elemental e raça bestial, possui capacidade de manipulação elemental e características corporais bestiais</td><td>Adora a natureza e a força, cultura selvagem e misteriosa, especializada em combate elemental e sobrevivência selvagem</td><td>Força de exploração selvagem e combate elemental da civilização de simbiose, desempenho proeminente na exploração de planos desconhecidos</td></tr></tbody></table><h2 id="_4-garantia-de-direitos-raciais" tabindex="-1">4. Garantia de Direitos Raciais <a class="header-anchor" href="#_4-garantia-de-direitos-raciais" aria-label="Permalink to &quot;4. Garantia de Direitos Raciais&quot;">​</a></h2><p>Sob o sistema da República de Todas as Raças, todas as raças inteligentes desfrutam de direitos legais iguais, as medidas de garantia específicas incluem:</p><ol><li><strong>Igualdade de direitos políticos</strong>: Cada raça tem assentos de representantes distribuídos proporcionalmente à população no Conselho de Âncora, e raças com menor população têm pelo menos um assento garantido.</li><li><strong>Garantia de direitos culturais</strong>: Cada raça tem o direito de preservar e desenvolver sua própria língua, escrita, religião, costumes e tradições culturais, e a civilização de simbiose estabelece fundos especiais para proteger a cultura de raças ameaçadas.</li><li><strong>Igualdade de direitos educacionais</strong>: Os membros de cada raça desfrutam de igual direito à educação, e o sistema educacional considera plenamente as características fisiológicas e cognitivas de diferentes raças, fornecendo planos educacionais diferenciados.</li><li><strong>Igualdade de direitos de cultivo</strong>: O sistema de cultivo de origem de trezentos conjuntos está aberto igualmente a todas as raças, e a alocação de recursos de cultivo considera plenamente as diferenças constitucionais e necessidades de energia de diferentes raças.</li><li><strong>Garantia de necessidades especiais</strong>: Para raças com necessidades fisiológicas especiais (como necessidades de ambiente de energia de raças elementais, necessidades de iluminação de raças vegetais), a civilização de simbiose fornece garantias direcionadas em instalações públicas e ambiente de habitação.</li></ol><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O Catálogo de Todas as Raças é a apresentação concreta do conceito de &quot;progresso conjunto de todas as raças&quot; da Civilização de Simbiose de Âncora. Da forma humanoide à forma consciente, da vida material à vida digital, cada raça contribui com força insubstituível para a civilização de simbiose com sua maneira única de existência. A República de Todas as Raças não significa assimilar todas as raças à raça humana, mas alcançar evolução conjunta com base no respeito à diversidade—esta é precisamente a razão fundamental pela qual a civilização de simbiose transcende a civilização de estilo de pilhagem.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>50-Visão Geral da Genealogia de Todas as Raças</li><li>51-Posição e Características da Raça Humana</li><li>77-Fundação da República de Todas as Raças</li></ul>',31)])])}const h=e(d,[["render",r]]);export{p as __pageData,h as default};
